using Domain.Core;

namespace Domain;

/// <summary>
/// Pizza. Raíz de agregado.
/// La relación con los ingredientes es un Set (no admite duplicados; la
/// igualdad de <see cref="Ingredient"/> es por identificador) y se expone
/// como colección inmutable.
/// El precio está desnormalizado: se almacena y se recalcula como el coste
/// de los ingredientes más un 20 % de beneficio cada vez que cambia el set.
/// Constructor y atributos protected.
/// </summary>
public class Pizza : AggregateRoot
{
    private const decimal ProfitMargin = 1.20m;

    private readonly HashSet<Ingredient> _ingredients;

    public string Name { get; protected set; }

    public string Description { get; protected set; }

    public string Url { get; protected set; }

    public decimal Price { get; protected set; }

    public IReadOnlySet<Ingredient> Ingredients => _ingredients;

    protected Pizza(
        Guid id,
        string name,
        string description,
        string url,
        IEnumerable<Ingredient> ingredients)
        : base(id)
    {
        Name = name;
        Description = description;
        Url = url;
        _ingredients = new HashSet<Ingredient>(ingredients);
        RecalculatePrice();
    }

    public static Pizza Create(
        Guid id,
        string name,
        string description,
        string url,
        IEnumerable<Ingredient> ingredients)
        => new(id, name, description, url, ingredients);

    public void Update(string name, string description, string url)
    {
        Name = name;
        Description = description;
        Url = url;
    }

    public void AddIngredient(Ingredient ingredient)
    {
        if (_ingredients.Add(ingredient))
        {
            RecalculatePrice();
        }
    }

    public void RemoveIngredient(Ingredient ingredient)
    {
        if (_ingredients.Remove(ingredient))
        {
            RecalculatePrice();
        }
    }

    private void RecalculatePrice()
    {
        Price = _ingredients.Sum(ingredient => ingredient.Cost) * ProfitMargin;
    }
}

